@prefix ospd: <https://w3id.org/ogc/ospd/activity-type/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode ospd:GA032 ;
            sh:resultMessage "An activity type should have a skos:definition." ;
            sh:resultPath skos:definition ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "An activity type should have a skos:definition." ;
                    sh:minCount 1 ;
                    sh:path skos:definition ;
                    sh:severity sh:Warning ] ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms true .

